EncodableList HostState::ToEncodableList() const {
  EncodableList list;
  list.reserve(8);
  list.push_back(CustomEncodableValue(permission_));
  list.push_back(CustomEncodableValue(server_));
  list.push_back(server_failure_ ? EncodableValue(*server_failure_) : EncodableValue());
  list.push_back(EncodableValue(token_));
  list.push_back(EncodableValue(token_remaining_seconds_));
  list.push_back(EncodableValue(token_regenerated_after_failures_));
  list.push_back(certificate_error_ ? EncodableValue(*certificate_error_) : EncodableValue());
  list.push_back(EncodableValue(streams_));
  return list;
}

HostState HostState::FromEncodableList(const EncodableList& list) {
  HostState decoded(
    std::any_cast<const ScreenPermission&>(std::get<CustomEncodableValue>(list[0])),
    std::any_cast<const ServerStatus&>(std::get<CustomEncodableValue>(list[1])),
    std::get<std::string>(list[3]),
    std::get<int64_t>(list[4]),
    std::get<bool>(list[5]),
    std::get<EncodableList>(list[7]));
  auto& encodable_server_failure = list[2];
  if (!encodable_server_failure.IsNull()) {
    decoded.set_server_failure(std::get<std::string>(encodable_server_failure));
  }
  auto& encodable_certificate_error = list[6];
  if (!encodable_certificate_error.IsNull()) {
    decoded.set_certificate_error(std::get<std::string>(encodable_certificate_error));
  }
  return decoded;
}

bool HostState::operator==(const HostState& other) const {
  return PigeonInternalDeepEquals(permission_, other.permission_) && PigeonInternalDeepEquals(server_, other.server_) && PigeonInternalDeepEquals(server_failure_, other.server_failure_) && PigeonInternalDeepEquals(token_, other.token_) && PigeonInternalDeepEquals(token_remaining_seconds_, other.token_remaining_seconds_) && PigeonInternalDeepEquals(token_regenerated_after_failures_, other.token_regenerated_after_failures_) && PigeonInternalDeepEquals(certificate_error_, other.certificate_error_) && PigeonInternalDeepEquals(streams_, other.streams_);
}

bool HostState::operator!=(const HostState& other) const {
  return !(*this == other);
}

size_t HostState::Hash() const {
  size_t result = 1;
  result = result * 31 + PigeonInternalDeepHash(permission_);
  result = result * 31 + PigeonInternalDeepHash(server_);
  result = result * 31 + PigeonInternalDeepHash(server_failure_);
  result = result * 31 + PigeonInternalDeepHash(token_);
  result = result * 31 + PigeonInternalDeepHash(token_remaining_seconds_);
  result = result * 31 + PigeonInternalDeepHash(token_regenerated_after_failures_);
  result = result * 31 + PigeonInternalDeepHash(certificate_error_);
  result = result * 31 + PigeonInternalDeepHash(streams_);
  return result;
}

std::ostream& operator<<(
  std::ostream& os,
  const HostState& obj) {
  os << "HostState(";
  os << "permission: ";
  os << PigeonInternalToString(obj.permission_);
  os << ", server: ";
  os << PigeonInternalToString(obj.server_);
  os << ", server_failure: ";
  if (obj.server_failure_) {
    os << PigeonInternalToString(*obj.server_failure_);
  }
  else {
    os << "null";
  }
  os << ", token: ";
  os << PigeonInternalToString(obj.token_);
  os << ", token_remaining_seconds: ";
  os << PigeonInternalToString(obj.token_remaining_seconds_);
  os << ", token_regenerated_after_failures: ";
  os << PigeonInternalToString(obj.token_regenerated_after_failures_);
  os << ", certificate_error: ";
  if (obj.certificate_error_) {
    os << PigeonInternalToString(*obj.certificate_error_);
  }
  else {
    os << "null";
  }
  os << ", streams: ";
  os << PigeonInternalToString(obj.streams_);
  os << ")";
  return os;
}

size_t PigeonInternalDeepHash(const HostState& v) {
  return v.Hash();
}


PigeonInternalCodecSerializer::PigeonInternalCodecSerializer() {}

EncodableValue PigeonInternalCodecSerializer::ReadValueOfType(
  uint8_t type,
  ::flutter::ByteStreamReader* stream) const {
  switch (type) {
    case 129: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ScreenPermission>(enum_arg_value));
      }
    case 130: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<ServerStatus>(enum_arg_value));
      }
    case 131: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<StreamStatus>(enum_arg_value));
      }
    case 132: {
        const auto& encodable_enum_arg = ReadValue(stream);
        const int64_t enum_arg_value = encodable_enum_arg.IsNull() ? 0 : encodable_enum_arg.LongValue();
        return encodable_enum_arg.IsNull() ? EncodableValue() : CustomEncodableValue(static_cast<StreamQuality>(enum_arg_value));
      }
    case 133: {
        return CustomEncodableValue(EndpointState::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 134: {
        return CustomEncodableValue(DisplayStreamState::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    case 135: {
        return CustomEncodableValue(HostState::FromEncodableList(std::get<EncodableList>(ReadValue(stream))));
      }
    default:
      return ::flutter::StandardCodecSerializer::ReadValueOfType(type, stream);
    }
}

void PigeonInternalCodecSerializer::WriteValue(
  const EncodableValue& value,
  ::flutter::ByteStreamWriter* stream) const {
  if (const CustomEncodableValue* custom_value = std::get_if<CustomEncodableValue>(&value)) {
    if (custom_value->type() == typeid(ScreenPermission)) {
      stream->WriteByte(129);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ScreenPermission>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(ServerStatus)) {
      stream->WriteByte(130);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<ServerStatus>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(StreamStatus)) {
      stream->WriteByte(131);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<StreamStatus>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(StreamQuality)) {
      stream->WriteByte(132);
      WriteValue(EncodableValue(static_cast<int>(std::any_cast<StreamQuality>(*custom_value))), stream);
      return;
    }
    if (custom_value->type() == typeid(EndpointState)) {
      stream->WriteByte(133);
      WriteValue(EncodableValue(std::any_cast<EndpointState>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(DisplayStreamState)) {
      stream->WriteByte(134);
      WriteValue(EncodableValue(std::any_cast<DisplayStreamState>(*custom_value).ToEncodableList()), stream);
      return;
    }
    if (custom_value->type() == typeid(HostState)) {
      stream->WriteByte(135);
      WriteValue(EncodableValue(std::any_cast<HostState>(*custom_value).ToEncodableList()), stream);
      return;
    }
  }
  ::flutter::StandardCodecSerializer::WriteValue(value, stream);
}

/// The codec used by HostUIControl.
